#!/bin/bash
# Print the three IP addresses that appear most often in access.log,
# one per line, most frequent first. Ties are broken by first
# appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '
{
    ip = $1
    if (ip == "") next
    count[ip]++
    if (!(ip in seen)) {
        seen[ip] = 1
        order[++n] = ip
    }
}
END {
    # Selection sort by (count desc, first appearance asc)
    for (i = 1; i <= 3 && i <= n; i++) {
        best = i
        for (j = i + 1; j <= n; j++) {
            if (count[order[j]] > count[order[best]] ||
                (count[order[j]] == count[order[best]] && seen[order[j]] < seen[order[best]]))
                best = j
        }
        if (best != i) {
            tmp = order[i]; order[i] = order[best]; order[best] = tmp
        }
        print order[i]
    }
}
' access.log
